-- Generated by scripts/vault-catalog.py. Do not edit by hand.
select public.ranked_season();  -- makes sure the current ranked season exists
on conflict (code) do update set starts_at = excluded.starts_at, ends_at = excluded.ends_at;
on conflict (code) do update set name = excluded.name, starts_at = excluded.starts_at, ends_at = excluded.ends_at;

on conflict (code) do update set name = excluded.name, description = excluded.description, metric = excluded.metric, target = excluded.target,
  event = excluded.event, reward_volts = excluded.reward_volts, reward_items = excluded.reward_items, sort = excluded.sort;

on conflict (slug) do update set name = excluded.name, slot = excluded.slot, tier = excluded.tier, description = excluded.description,
  unlock = excluded.unlock, price = excluded.price, achievement = excluded.achievement, event = excluded.event, contents = excluded.contents,
  sort = excluded.sort, active = true;

-- Achievements no longer offered are removed unless someone already completed them.
delete from public.achievements a where a.code not in ('first-light', 'week-warrior', 'devotee', 'perfect-circuit', 'ultralinker', 'eternal-flame', 'ranked-debut', 'frenzy-champ', 'unbreakable', 'into-the-fire', 'ice-king', 'the-scientist', 's1-pioneer', 's1-founder', 'snowed-in', 'twelve-days', 'scientist-legacy', 'first-spark') and not exists (select 1 from public.player_achievements pa where pa.code = a.code);
-- Items no longer in the catalogue stay in the table (owners keep them) but are hidden from the Vault.
update public.cosmetic_items set active = false where slug not in ('base-classic-spark', 'bulb-red', 'bulb-gold', 'bulb-blue', 'bulb-green', 'hat-cap', 'hat-beanie', 'head-bucket', 'hat-sprout', 'out-navy-hoodie', 'out-tee', 'out-grey-tee', 'out-stripe-tee', 'ban-classic', 'ban-sky', 'ban-sunset', 'ban-mint', 'bulb-pink', 'bulb-orange', 'bulb-violet', 'bulb-cyan', 'base-grin', 'base-dreamer', 'out-blue-hoodie', 'out-puffer', 'hat-party', 'hat-headphones', 'head-propeller', 'eyes-round', 'eyes-shades', 'acc-coffee', 'acc-book', 'fx-glow', 'ban-forest', 'ban-ocean', 'bulb-fade-sunset', 'bulb-fade-ocean', 'bulb-fade-mint', 'hat-tophat', 'hat-wizard', 'eyes-star', 'eyes-visor', 'out-dark-tech', 'out-midnight-hoodie', 'acc-flask', 'fx-sparks', 'ban-grid', 'bulb-fade-twilight', 'bulb-rose-gold', 'out-varsity', 'head-viking', 'hat-halo', 'eyes-watt-specs', 'acc-lightning-rod', 'ban-voltage', 'bulb-molten-gold', 'bulb-neon-pulse', 'out-lab-coat', 'head-royal-crown', 'fx-golden-shimmer', 'ban-aurora', 'bulb-s1-aurora', 'head-s1-beanie', 'fx-winter-snow', 'head-santa', 'bulb-candy-cane', 'bulb-frost', 'out-xmas-sweater', 'base-neon', 'base-circuit', 'base-overload', 'base-professor-watt', 'bundle-neon', 'bundle-circuit', 'bundle-overload', 'bundle-professor', 'ban-first-light', 'acc-torch', 'eyes-starlight', 'out-perfect-circuit', 'bulb-eternal-flame', 'ban-ranked', 'head-frenzy-crown', 'fx-unbreakable', 'out-inferno-jacket', 'head-ice-king', 'base-scientist', 'ban-scientist', 'ban-s1', 'out-s1-founder', 'ban-winter', 'acc-candy-cane', 'fx-scientist-legacy', 'base-first-spark');
-- D41: the filament slot is gone. Looks no longer carry a filament, equip ignores one if an old client sends it,
-- and every filament item is hidden (the v4 catalogue already marks them inactive).

create or replace function public.vault_default_look() returns jsonb
language sql immutable as $$
  select jsonb_build_object('v', 2, 'base', 'base-classic-spark', 'bulb', 'bulb-gold',
    'outfit', 'out-navy-hoodie', 'head', null, 'eyes', null, 'acc', null, 'fx', null, 'banner', 'ban-classic')
$$;

create or replace function public.vault_equip(p_look jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me uuid := public.me(); slot_name text; it text; look jsonb := '{"v": 2}'::jsonb;
  required text[] := array['base', 'bulb', 'outfit', 'banner'];
begin
  if auth.uid() is null then raise exception 'not authenticated' using errcode = '28000'; end if;
  foreach slot_name in array array['base', 'bulb', 'outfit', 'head', 'eyes', 'acc', 'fx', 'banner'] loop
    it := nullif(p_look ->> slot_name, '');
    if it is null then
      if slot_name = any(required) then it := public.vault_default_look() ->> slot_name; end if;
    else
      if not exists (select 1 from public.cosmetic_items where slug = it and slot = slot_name) then
        raise exception 'item % does not go in %', it, slot_name using errcode = '22023';
      end if;
      if not public.vault_owns(me, it) then raise exception 'you do not own %', it using errcode = '42501'; end if;
    end if;
    look := look || jsonb_build_object(slot_name, it);
  end loop;
  delete from public.vault_equipped where player_id = me;
  select me, k, v from jsonb_each_text(look) e(k, v) where k <> 'v' and v is not null;
  update public.players set avatar = look where id = me;
  return look;
end $$;

update public.cosmetic_items set active = false where slot = 'filament';
update public.players set avatar = avatar - 'filament' where avatar ? 'filament';
delete from public.vault_equipped where slot = 'filament';
